 const activeProfileRef=useRef('default');activeProfileRef.current=activeProfile;
 const [capture,setCapture]=useState(false),[captureContext,setCaptureContext]=useState<any>(null);
 const profileDirty=useRef(false);
 const stripRef=useRef<HTMLDivElement>(null),menuDialog=useRef<HTMLDialogElement>(null);
 useEffect(()=>{const d=menuDialog.current;if(menu&&!d?.open)d?.showModal();if(!menu&&d?.open)d?.close();if(!menu)return;const previous=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.body.style.overflow=previous}},[menu]);
 useEffect(()=>{const q=window.matchMedia('(min-width:700px)');const close=()=>{if(q.matches)setMenu(false)};q.addEventListener('change',close);return()=>q.removeEventListener('change',close)},[]);
 const audio=useRecorderAudio(),audioRef=useRef(audio);audioRef.current=audio;
 const availableExercises=EXERCISES.filter(e=>supportsExercise(e,profile.system));
 const ex=EXERCISES.find(e=>e.id===exerciseId)!,attempts=scopedRows(rows,activeProfile).filter(r=>r.kind==='attempt'),plan=recommend(attempts,profile.system),active=audio.index>=0&&audio.index<ex.events.length?ex.events[audio.index]:null,activeNote=active?.n||selectedNote;
 useEffect(()=>{function hash(){const t=location.hash.slice(1);if(TABS.some(a=>a[0]===t)){audioRef.current.stop();setTab(t)}}hash();const id=localStorage.getItem('flauta-active-profile')||'default';activeProfileRef.current=id;setActiveProfile(id);window.addEventListener('hashchange',hash);load();return()=>window.removeEventListener('hashchange',hash)},[]);
 useEffect(()=>{const refresh=()=>{if(!document.hidden)void load()};window.addEventListener('focus',refresh);return()=>window.removeEventListener('focus',refresh)},[]);
 useEffect(()=>{const strip=stripRef.current;if(!strip||audio.index<0)return;const child=strip.children[audio.index] as HTMLElement|undefined;if(child)strip.scrollTo({left:Math.max(0,child.offsetLeft-strip.offsetLeft-strip.clientWidth/2+child.clientWidth/2),behavior:'smooth'})},[audio.index]);
 useEffect(()=>{if(!supportsExercise(ex,profile.system)){audioRef.current.stop();setExerciseId('primer-si');setFrom(0);setTo(EXERCISES[0].events.length-1);setResult(null);setRecorded(false)}if(!fingeringFor(selectedNote,profile.system)){audioRef.current.stop();setSelectedNote('B5')}},[profile.system,exerciseId,selectedNote]);
 useEffect(()=>{if(to>=ex.events.length)setTo(ex.events.length-1)},[exerciseId]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),5500);return()=>clearTimeout(t)},[toast]);
 async function load(){try{const r=await fetch('/api/state',{signal:AbortSignal.timeout(10000)});if(!r.ok){setSync(r.status===401?'login':'error');return}const data=await r.json() as any;setRows(data.rows);const p=data.rows.find((r:any)=>r.kind==='profile'),next=learnerSettings(p);setSettings(next);let id=activeProfileRef.current;if(!next.learners.some(l=>l.id===id))id=next.learners[0].id;setActiveProfile(id);activeProfileRef.current=id;const learner=next.learners.find(l=>l.id===id)!;if(!profileDirty.current)setProfile({name:learner.name,system:learner.system,minutes:learner.minutes});setSession(scopedRows(data.rows,id).find((r:any)=>r.kind==='session')||null);setSync('ok');await loadFiles()}catch{setSync('error')}}
 async function loadFiles(){const r=await fetch('/api/files');if(r.ok){const d=await r.json() as any;setFiles(d.files)}}
 async function persist(kind:string,value:any){if(kind==='attempt'&&!value.attemptId)value={...value,attemptId:crypto.randomUUID()};if(kind==='attempt'||kind==='session')value={...value,profileId:activeProfile,instrumentId:settings.learners.find(l=>l.id===activeProfile)?.instrumentId||'flute-1'};const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,value})});const d=await r.json() as any;if(!r.ok)throw Error(d.error||'No se pudo guardar.');if(kind==='attempt'||kind==='session')setRows(a=>[{...value,id:d.id,kind,date:Date.now()},...a.filter(r=>r.id!==d.id)]);return d}
 function navigate(t:string,practiceNote?:string){audio.stop();if(t==='practica')setSelectedNote(practiceNote||ex.events.find(e=>e.n)?.n||'B5');setTab(t);setMenu(false);history.replaceState(null,'','#'+t);setResult(null)}
 function choose(id:string){if(!supportsExercise(EXERCISES.find(e=>e.id===id)!,profile.system)){setToast('Esta práctica incluye una nota pendiente de incorporar a la guía alemana.');return}audio.stop();setExerciseId(id);setSelectedNote(EXERCISES.find(e=>e.id===id)?.events.find(e=>e.n)?.n||'B5');setFrom(0);setTo(EXERCISES.find(e=>e.id===id)!.events.length-1);setResult(null);setRecorded(false);navigate('practica',EXERCISES.find(e=>e.id===id)?.events.find(e=>e.n)?.n||'B5')}
 async function done(r:any){r={...r,attemptId:r.attemptId||crypto.randomUUID()};setResult(r);try{await persist('attempt',r);setRecorded(true);setToast('Práctica guardada en tu progreso.')}catch(e){setToast((e as Error).message)}}
 async function startListen(){try{setResult(null);setRecorded(false);setCaptureContext({profileId:activeProfile,instrumentId:settings.learners.find(l=>l.id===activeProfile)?.instrumentId||'flute-1',exerciseId:ex.id});if(capture&&typeof MediaRecorder==='undefined')setToast('Este navegador permite medir el micrófono, pero no grabar el intento. Prueba Safari o Chrome actualizado.');await audio.listen(ex,mode,speed,metronome,done,capture)}catch(e){setToast((e as Error).message)}}
 async function saveProfile(e:any){e.preventDefault();setBusy(true);try{await saveSettings({...settings,learners:settings.learners.map(l=>l.id===activeProfile?{...l,...profile,system:profile.system as Learner['system']}:l),instruments:settings.instruments.map(i=>i.id===settings.learners.find(l=>l.id===activeProfile)?.instrumentId?{...i,system:profile.system as Instrument['system']}:i)});profileDirty.current=false;setSelectedNote('B5');setToast('Perfil guardado correctamente.')}catch(e){setToast((e as Error).message)}finally{setBusy(false)}}
 async function setAia(s:any){if(s.index===2&&s.self?.at(-1)?.value==='Me ha costado'){const pos=EXERCISES.findIndex(e=>e.id===s.exerciseId);s={...s,exerciseId:EXERCISES[Math.max(0,pos-1)].id,simplified:true}}setBusy(true);try{await persist('session',s);setSession({...s,profileId:activeProfile});setToast('Sesión AIA guardada.')}catch(e){setToast((e as Error).message)}finally{setBusy(false)}}
 async function upload(file:File){setBusy(true);try{const data=new FormData();data.append('file',file);const r=await fetch('/api/files',{method:'POST',body:data});const d=await r.json() as any;if(!r.ok)throw Error(d.error);await loadFiles();setToast('Archivo guardado. Puedes abrirlo para revisarlo.')}catch(e){setToast((e as Error).message)}finally{setBusy(false)}}
 async function saveSettings(next:{learners:Learner[];instruments:Instrument[]}){next={...next,learners:next.learners.map(l=>({...l,system:recorderSystem(next.instruments.find(i=>i.id===l.instrumentId),l.system)}))};const current=next.learners.find(l=>l.id===activeProfile)||next.learners[0];await persist('profile',{...current,learners:next.learners,instruments:next.instruments});setSettings(next);setProfile({name:current.name,system:current.system,minutes:current.minutes});profileDirty.current=false;}
 async function applySettings(next:{learners:Learner[];instruments:Instrument[]}){setBusy(true);try{await saveSettings(next);setToast('Cambios guardados.')}catch(e){setToast((e as Error).message);throw e}finally{setBusy(false)}}
 function selectProfile(id:string){audio.stop();audio.clearRecording();const learner=settings.learners.find(l=>l.id===id)!;setActiveProfile(id);activeProfileRef.current=id;localStorage.setItem('flauta-active-profile',id);setProfile({name:learner.name,system:learner.system,minutes:learner.minutes});profileDirty.current=false;setSession(scopedRows(rows,id).find(r=>r.kind==='session')||null);setExerciseId('primer-si');setSelectedNote('B5');setResult(null);setRecorded(false);setToast('Perfil activo: '+learner.name);}
 async function selectInstrument(id:string){const instrument=settings.instruments.find(i=>i.id===id)!;if(instrument.system==='yrf21'){setToast('El pífano tiene digitación propia. Consulta su ficha en Mi instrumento; los ejercicios actuales son para flauta dulce.');return}audio.stop();try{await applySettings({...settings,learners:settings.learners.map(l=>l.id===activeProfile?{...l,instrumentId:id,system:recorderSystem(instrument,l.system)}:l)});setSelectedNote('B5');}catch{}}
